{"script":"() => {
  // Set the search to Kindle Store
  const select = document.querySelector('#searchDropdownBox');
  if (select) {
    select.value = 'search-alias=digital-text';
    select.dispatchEvent(new Event('change', { bubbles: true }));
  }
  // Set the search term
  const input = document.querySelector('#twotabsearchtextbox');
  if (input) {
    input.value = 'roman empire history';
    input.dispatchEvent(new Event('input', { bubbles: true }));
  }
  return { selectValue: select ? select.value : null, inputValue: input ? input.value : null };
}"}

