{"script":"() => {
  // Find the sort dropdown
  const sortEl = document.querySelector('#s-result-sort-select') || document.querySelector('[data-id="sort"]') || document.querySelector('select#sort');
  // Look for sort options
  const sortButtons = document.querySelectorAll('[aria-label*="Sort"], [data-action*="sort"]');
  return {
    dateNow: new Date().toDateString(),
    sortElExists: !!sortEl,
    sortOptions: sortEl ? Array.from(sortEl.options).map(o => ({value: o.value, text: o.text})) : null,
    buttonCount: sortButtons.length,
  };
}"}

