{"script":"() => {
  // Extract all visible book info from the page
  const items = document.querySelectorAll('[data-component-type="s-search-result"]');
  const result = [];
  items.forEach(item => {
    const titleEl = item.querySelector('h2 a span, h2 span');
    const title = titleEl ? titleEl.textContent.trim() : null;
    const authorEl = item.querySelector('.a-row.a-size-base+ .a-row .a-size-base, .a-row.a-spacing-none .a-size-base');
    const author = authorEl ? authorEl.textContent.trim() : null;
    const dateText = item.textContent.match(/(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+\d+,\s+\d{4}/);
    result.push({ title, dateText: dateText ? dateText[0] : null });
  });
  // Get current date
  const now = new Date();
  return { 
    now: now.toString(), 
    nowISO: now.toISOString(),
    itemCount: items.length,
    items: result.slice(0, 20)
  };
}"}

